let projectDocs={};
function guideFor(g){
 const manual=PROJECT_GUIDES[String(g.repo||'').toLowerCase()];if(manual)return {...manual,reviewed:true};
 if(g.browser){if(!safeURL(g.links?.play))return {requirements:[g.limitations||'Acompanhe as fontes oficiais para verificar a disponibilidade.'],steps:[],note:'Este registro não tem um acesso jogável confirmado. Consulte as notícias e as fontes do projeto.'};
 return {requirements:[g.status||'Confira a disponibilidade na página oficial.',g.limitations||'Confira os requisitos informados pelo projeto.'],steps:[['Abra a página do jogo','Use o botão Jogar para acessar o endereço indicado pelo projeto.'],['Confira os requisitos','Leia as orientações da página antes de carregar o jogo. Se forem solicitados arquivos originais, use os da sua própria cópia.'],['Configure e experimente','Siga os comandos e as opções apresentados pelo projeto para configurar os controles e iniciar.']],note:'A disponibilidade do endereço não confirma que o jogo possa ser concluído. O desempenho depende do projeto e do dispositivo.'};}
 return {source:safeURL(g.url)+'#readme',requirements:['Confira os sistemas, dependências e arquivos necessários na documentação oficial.'],steps:[['Comece pelo README','Abra o README do projeto e localize as instruções de instalação ou primeiros passos nos links desta página.'],['Confira a distribuição',g.release?'Abra a página da versão publicada e confira os arquivos disponíveis para seu sistema. Uma release também pode conter somente código ou ferramentas.':'Não há uma release identificada no catálogo. Consulte o README para saber se é necessário compilar ou se há outro canal de distribuição.'],['Prepare os arquivos necessários','Se o autor solicitar dados do jogo original, use os arquivos da sua cópia e confira a versão e a região exigidas.'],['Siga a execução oficial','Use o procedimento de instalação ou compilação indicado pelo autor. Os nomes dos programas e os diretórios variam entre projetos.']],note:'Este é um roteiro geral de acesso à documentação. Os passos específicos deste projeto ainda não foram resumidos em português.'};
}
function externalLink(label,url,cls=''){return safeURL(url)?'<a class="'+cls+'" href="'+esc(safeURL(url))+'" target="_blank" rel="noopener noreferrer">'+esc(label)+' ↗</a>':''}
function renderProject(g){
 const guide=guideFor(g),docs=projectDocs[String(g.repo||'').toLowerCase()],links=docs?.links||[];
 document.title=g.title+' — jogosrecompilados.com.br';
 $('#projectContent').innerHTML='<section class="project-hero"><div class="project-overview"><span class="eyebrow">'+esc(labels[g.type])+'</span><h1>'+esc(g.title)+'</h1><p class="project-by">'+esc(g.repo||g.publisher||'Projeto comunitário')+'</p><div class="project-facts"><span>'+esc(g.platform||'Plataforma não informada')+'</span><span>☆ '+Number(g.stars||0).toLocaleString('pt-BR')+' estrelas</span><span>'+esc(g.browser?g.status:g.release?'Versão '+g.release:'Sem release identificada')+'</span></div><p class="project-summary">'+esc(g.browser?g.description:guide.reviewed?'Conheça o projeto e siga o passo a passo em português para começar.':'Acesse os links oficiais e o guia de primeiros passos deste projeto.')+'</p><div class="project-actions">'+externalLink(g.browser?'Fonte do projeto':'GitHub do projeto',g.url,'primary')+'<a class="secondary" href="#guia">Ver guia ↓</a><button id="projectFavorite" class="secondary" aria-pressed="'+favorites.has(g.id)+'">'+(favorites.has(g.id)?'♥ Favoritado':'♡ Favoritar')+'</button></div></div><div class="project-visual"><img id="projectImage" src="'+esc(picture(g))+'" alt="'+esc(g.title)+'"><span>'+esc(g.platform||'Comunidade')+'</span></div></section><div class="project-layout"><section class="project-guide" id="guia"><div class="eyebrow">DO PROJETO AO PRIMEIRO PLAY</div><h2>'+(g.browser?'Como acessar':guide.reviewed?'Como começar a jogar':'Primeiros passos')+'</h2><p class="guide-intro">'+(guide.reviewed?'Resumo em português do README oficial, conferido em '+date(guide.checked)+'.':g.browser?'Orientações com base nas fontes e nas limitações do catálogo.':'Um roteiro para encontrar as instruções corretas na documentação do projeto.')+'</p><div class="requirements"><h3>Antes de começar</h3><ul>'+guide.requirements.map(text=>'<li>'+esc(text)+'</li>').join('')+'</ul></div><ol class="guide-steps">'+guide.steps.map(([title,text])=>'<li><h3>'+esc(title)+'</h3><p>'+esc(text)+'</p></li>').join('')+'</ol>'+(guide.note?'<p class="guide-note">'+esc(guide.note)+'</p>':'')+'</section><aside class="project-sidebar"><section><h2>Links do projeto</h2><div class="project-resource-list">'+cardLinks(g)+(guide.source?externalLink('README original',guide.source):'')+(guide.links||[]).map(([label,url])=>externalLink(label,url)).join('')+'</div></section>'+(links.length?'<section><h2>Documentação oficial</h2><div class="project-resource-list">'+links.map(link=>externalLink(link.label,link.url)).join('')+'</div><p class="source-date">README consultado em '+date(docs.checked)+'.</p></section>':'')+'<section><h2>Sobre esta versão</h2><p>Última atividade: '+date(g.last_commit)+'.</p>'+(g.archived?'<p>O repositório está arquivado.</p>':'')+'<p>Confira os requisitos e as notas do autor antes de instalar ou atualizar.</p></section></aside></div>';
 bindImageFallback($('#projectImage'),g);
 $('#projectFavorite').onclick=()=>{favorites.has(g.id)?favorites.delete(g.id):favorites.add(g.id);try{localStorage.setItem('atlas-favorites',JSON.stringify([...favorites]))}catch{}const b=$('#projectFavorite');b.setAttribute('aria-pressed',String(favorites.has(g.id)));b.textContent=favorites.has(g.id)?'♥ Favoritado':'♡ Favoritar'};
}
async function initProject(){
 const id=new URLSearchParams(location.search).get('id');if(!id){$('#projectContent').innerHTML='<h1>Escolha um projeto</h1><p>Volte ao catálogo para abrir o jogo que você quer conhecer.</p>';return}
 let best=null,found=false;
 try{const cached=JSON.parse(localStorage.getItem('atlas-catalog')||'null');if(cached){normalized(cached);best=cached}}catch{}
 try{const bundled=await getJSON('catalog.json');normalized(bundled);if(!best||Date.parse(bundled.generated_at)>Date.parse(best.generated_at))best=bundled}catch{}
 const show=data=>{const g=normalized(data).find(g=>g.id===id);if(g){found=true;renderProject(g)}return g};
 if(best)show(best);
 getJSON('project-docs.json').then(data=>{projectDocs=data.projects||{};if(best)show(best)}).catch(()=>{});
 try{const live=await getJSON(SOURCE+'data/games.json');normalized(live);best=live;show(live);try{localStorage.setItem('atlas-catalog',JSON.stringify(live))}catch{}}catch{}
 if(!found)$('#projectContent').innerHTML='<h1>Projeto não encontrado</h1><p>Ele pode ter mudado de endereço ou a fonte está indisponível. Procure o nome no catálogo.</p>';
}
initProject();
